/* @prim:begin 68-spec-rows */
.spec { display: flex; flex-direction: column; margin: 0; }
.specrow { display: grid; grid-template-columns: 9.5rem minmax(0, 1fr); column-gap: var(--sp-3, 24px); padding: var(--sp-2, 16px) 0; border-top: 1px solid var(--border); }
.specrow:last-child { border-bottom: 1px solid var(--border); }
.specrow dt { font-weight: 600; color: var(--text); }
.specrow dd { margin: 0; color: var(--text-secondary); text-wrap: pretty; }
.spec.cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--sp-2, 16px); }
.spec.cards > .specrow, .spec.cards > .specrow:last-child { grid-template-columns: minmax(0, 1fr); align-content: start; row-gap: var(--sp-1, 8px); padding: var(--sp-2, 16px) var(--sp-3, 24px); background: var(--surface); border: 1px solid var(--border); border-radius: var(--ds-r-md); }
.spec.cards > .specrow dt { display: flex; align-items: center; gap: var(--sp-1, 8px); font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--cyan); }
.spec.cards > .specrow dt::before { content: ""; width: 8px; height: 8px; border-radius: var(--ds-r-pill); background: currentColor; flex-shrink: 0; }
@media (max-width: 640px) { .specrow { grid-template-columns: minmax(0, 1fr); row-gap: 4px; } .spec.cards { grid-template-columns: minmax(0, 1fr); } }
@container (max-width: 40rem) { .specrow { grid-template-columns: minmax(0, 1fr); row-gap: 4px; } .spec.cards { grid-template-columns: minmax(0, 1fr); } }
@media print { .spec { break-inside: avoid; } .specrow { grid-template-columns: 8rem minmax(0, 1fr); padding: 7px 0; break-inside: avoid; } .spec.cards { display: flex; gap: 0; } .spec.cards > .specrow { background: none; border: 0; border-top: 1px solid var(--border); border-radius: 0; padding: 7px 0; } }
/* @prim:end 68-spec-rows */

